## New v3 JSON

Use one pane payload for all tabs. The following shows the resulting format after a browser has intentionally been moved into a terminal tab:

```json
{
  "version": 3,
  "timestamp": 1787293000000,
  "activeWorkspaceId": "alpha",
  "workspaces": {
    "alpha": {
      "workspaceId": "alpha",
      "repoRoot": "/repo/alpha",
      "activeWorktreePath": "/repo/alpha",
      "worktrees": [
        {
          "path": "/repo/alpha",
          "branch": "refs/heads/main",
          "head": "abc123",
          "isMain": true,
          "isLocked": false
        }
      ],
      "layout": {
        "activeTabId": "tab-workspace",
        "tabs": [
          {
            "id": "tab-workspace",
            "kind": "pane",
            "label": "Workspace",
            "pinned": false,
            "pane": {
              "paneTree": {
                "type": "split",
                "direction": "horizontal",
                "ratio": 0.6,
                "first": {
                  "type": "leaf",
                  "leafId": "leaf-terminal"
                },
                "second": {
                  "type": "leaf",
                  "leafId": "leaf-browser"
                }
              },
              "contentByLeafId": {
                "leaf-terminal": {
                  "kind": "terminal",
                  "sessionId": "session-1"
                },
                "leaf-browser": {
                  "kind": "browser",
                  "url": "https://example.com/docs",
                  "title": "Documentation",
                  "profileId": "default",
                  "worktreePath": "/repo/alpha",
                  "worktreeLabel": "main"
                }
              },
              "activeLeafId": "leaf-browser",
              "expandedLeafId": null
            }
          }
        ],
        "tabGroups": [
          {
            "id": "group-default",
            "tabIds": ["tab-workspace"],
            "activeTabId": "tab-workspace"
          }
        ],
        "tabGroupLayout": {
          "type": "group",
          "groupId": "group-default"
        },
        "focusedGroupId": "group-default"
      },
      "terminalSessions": {
        "session-1": {
          "localSessionId": "session-1",
          "backendSessionId": "pty-1",
          "worktreePath": "/repo/alpha",
          "cwd": "/repo/alpha",
          "createdAt": 1787293000000
        }
      }
