fn get_local_ip() -> Option<String> {
    use std::net::UdpSocket;
    let socket = UdpSocket::bind("0.0.0.0:0").ok()?;
    socket.connect("8.8.8.8:80").ok()?;
    socket.local_addr().ok().map(|addr| addr.ip().to_string())
}

use crate::ipc::{run_blocking, IpcError};
use crate::worktree::{run_git, WorkspaceRegistry, WorktreeError, WorktreeManager};
use serde::{Deserialize, Serialize};
use std::path::{Path, PathBuf};
use tauri::State;

/// Workspace ID that shipped as a hard-coded alias for the startup repository.
/// It is no longer registered. Clients that persisted it migrate by calling
/// [`cmd_project_initial`] on startup and adopting the canonical ID it returns.
pub const LEGACY_DEFAULT_WORKSPACE_ID: &str = "default";

/// Fallback ID for a root whose folder name carries no usable characters.
const FALLBACK_WORKSPACE_ID: &str = "project";

/// Derives the canonical workspace ID for a repository root from its folder
/// name, restricted to characters `WorkspaceRegistry::validate_workspace_id`
/// accepts (no separators, whitespace, control characters, or leading `-`).
pub fn derive_workspace_id(repo_root: &Path) -> String {
    repo_root
        .file_name()
        .and_then(|name| name.to_str())
        .map(|name| {
            let slug: String = name
                .chars()
                .map(|ch| {
                    if ch.is_alphanumeric() || ch == '_' || ch == '-' {
                        ch
                    } else {
                        '-'
                    }
                })
                .collect();
            let trimmed = slug.trim_matches('-');
            if trimmed.is_empty() {
                FALLBACK_WORKSPACE_ID.to_string()
            } else {
                trimmed.to_string()
            }
        })
        .unwrap_or_else(|| FALLBACK_WORKSPACE_ID.to_string())
}

/// Registers (idempotently) and returns the single canonical project for the
/// startup repository.
///
/// The ID is derived from the repository root reported by Git, not from the
/// process working directory, so launching from a subdirectory (`src-tauri/`,
/// a worktree checkout, a test harness) still yields one stable project ID.
pub fn initial_project(registry: &WorkspaceRegistry) -> Result<RegisteredProject, IpcError> {
    let cwd = std::env::current_dir().map_err(|error| {
        IpcError::from(WorktreeError::InvalidPath {
            path: PathBuf::from("."),
            reason: format!("the startup working directory is unavailable: {error}"),
        })
    })?;
    register_canonical_project(registry, &cwd, None)
}

/// Registers a repository root under exactly one workspace ID.
///
/// Canonical-root uniqueness: a root already registered under some ID resolves
/// to that existing project instead of gaining a second alias, so the registry
/// holds at most one ID per repository root. When `preferred_id` is `None` the
/// ID is derived from the root's folder name.
fn register_canonical_project(
    registry: &WorkspaceRegistry,
    repo_path: &Path,
    preferred_id: Option<&str>,
) -> Result<RegisteredProject, IpcError> {
    // `try_new` walks up to the Git top level, canonicalizes it, and rejects
    // non-Git paths, so the uniqueness check below compares canonical roots.
    let repo_root = WorktreeManager::try_new(repo_path)
        .map_err(IpcError::from)?
        .repo_root()
        .to_path_buf();

    if let Some((workspace_id, _)) = registry
        .list()
        .into_iter()
        .find(|(_, manager)| manager.repo_root() == repo_root)
    {
        return Ok(RegisteredProject {
            workspace_id,
            repo_root,
        });
    }

    let workspace_id = match preferred_id {
        Some(requested) => requested.to_string(),
        None => derive_workspace_id(&repo_root),
    };
    registry
        .register(&workspace_id, &repo_root)
        .map_err(IpcError::from)?;
    let repo_root = registry.repo_root(&workspace_id).map_err(IpcError::from)?;
    Ok(RegisteredProject {
        workspace_id,
        repo_root,
    })
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
pub struct RegisterProjectRequest {
    pub workspace_id: String,
    pub repo_path: PathBuf,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct RegisteredProject {
    pub workspace_id: String,
    pub repo_root: PathBuf,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
pub struct ProjectBranchesRequest {
    pub workspace_id: String,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct LocalBranch {
    pub name: String,
    pub is_current: bool,
}

/// Registers a project, enforcing one workspace ID per canonical repository
/// root. Requesting a new ID for an already-registered root is not an error:
/// the existing project is returned, so a client holding a stale ID (such as
/// the legacy `default`) migrates onto the canonical one instead of creating a
/// duplicate alias. Callers must adopt the returned `workspaceId`.
#[tauri::command]
pub async fn cmd_project_register(
    registry: State<'_, WorkspaceRegistry>,
    request: RegisterProjectRequest,
) -> Result<RegisteredProject, IpcError> {
    let registry = (*registry).clone();
    run_blocking(move || {
        register_canonical_project(
            &registry,
            &request.repo_path,
            Some(request.workspace_id.as_str()),
        )
    })
    .await
}

/// Returns the one canonical project for the repository the app was started
/// from, registering it on first call. Replaces the previous startup behaviour
/// of registering both a derived ID and a `default` alias for the same root.
#[tauri::command]
pub async fn cmd_project_initial(
    registry: State<'_, WorkspaceRegistry>,
) -> Result<RegisteredProject, IpcError> {
    let registry = (*registry).clone();
    run_blocking(move || initial_project(&registry)).await
}

#[tauri::command]
pub async fn cmd_project_branches(
    registry: State<'_, WorkspaceRegistry>,
    request: ProjectBranchesRequest,
) -> Result<Vec<LocalBranch>, IpcError> {
    let registry = (*registry).clone();
    run_blocking(move || {
        let manager = registry
            .manager(&request.workspace_id)
            .map_err(IpcError::from)?;
        let branch_output = run_git(
            manager.repo_root(),
            &[
                "for-each-ref",
                "--sort=refname",
                "--format=%(refname:short)",
                "refs/heads/",
            ],
        )
        .map_err(IpcError::from)?;
        let current_output =
            run_git(manager.repo_root(), &["branch", "--show-current"]).map_err(IpcError::from)?;
        let current = current_output.trim();

        let mut branches = branch_output
            .lines()
            .map(str::trim)
            .filter(|name| !name.is_empty())
            .map(|name| LocalBranch {
                name: name.to_string(),
                is_current: !current.is_empty() && name == current,
            })
            .collect::<Vec<_>>();
        branches.sort_by(|left, right| left.name.cmp(&right.name));
        Ok(branches)
    })
    .await
}

// allow: SIZE_OK — IPC module bundling terminal commands, output batching, and macOS libproc CWD resolution within constrained write scope
use crate::daemon::client::{DaemonAttachment, DaemonClient};
use crate::daemon::protocol::DaemonStreamMessage;
use crate::ipc::{run_blocking, IpcError};
use crate::terminal::TerminalSignal;
use crate::worktree::{WorkspaceRegistry, WorktreeError, WorktreeIdentity};
use base64::{engine::general_purpose::STANDARD, Engine as _};
use parking_lot::Mutex;
use serde::{Deserialize, Serialize};
use std::collections::HashMap;
use std::path::PathBuf;
use std::sync::Arc;
use std::time::{Duration, Instant};
use tauri::{AppHandle, Emitter, Runtime, State};

pub const TERMINAL_OUTPUT_EVENT: &str = "terminal_output";
pub const TERMINAL_LIFECYCLE_EVENT: &str = "terminal_lifecycle";

const BATCH_FLUSH_INTERVAL: Duration = Duration::from_millis(10);
const BATCH_MAX_BYTES: usize = 32 * 1024;
const CWD_CACHE_TTL: Duration = Duration::from_millis(500);

static CWD_CACHE: Mutex<Option<HashMap<String, (Instant, PathBuf)>>> = Mutex::new(None);

pub fn get_cached_cwd(session_id: &str) -> Option<PathBuf> {
    let mut guard = CWD_CACHE.lock();
    let map = guard.as_mut()?;
    if let Some((cached_at, cwd)) = map.get(session_id) {
        if cached_at.elapsed() < CWD_CACHE_TTL {
            return Some(cwd.clone());
        }
        map.remove(session_id);
    }
    None
}

pub fn update_cached_cwd(session_id: String, cwd: PathBuf) {
    let mut guard = CWD_CACHE.lock();
    let map = guard.get_or_insert_with(HashMap::new);
    map.insert(session_id, (Instant::now(), cwd));
}

pub fn invalidate_cached_cwd(session_id: &str) {
    let mut guard = CWD_CACHE.lock();
    if let Some(map) = guard.as_mut() {
        map.remove(session_id);
    }
}

struct PumpHandle {
    task: tokio::task::JoinHandle<()>,
    stream_task: tokio::task::JoinHandle<()>,
}

static ACTIVE_PUMPS: Mutex<Option<HashMap<String, PumpHandle>>> = Mutex::new(None);

pub fn stop_managed_pump(session_id: &str) {
    let mut guard = ACTIVE_PUMPS.lock();
    if let Some(map) = guard.as_mut() {
        if let Some(pump) = map.remove(session_id) {
            pump.task.abort();
            pump.stream_task.abort();
        }
    }
}

pub fn start_managed_pump<R: Runtime>(
    session_id: String,
    app_handle: AppHandle<R>,
    attachment: DaemonAttachment,
) {
    let mut guard = ACTIVE_PUMPS.lock();
    let map = guard.get_or_insert_with(HashMap::new);

    if let Some(old_pump) = map.remove(&session_id) {
        old_pump.task.abort();
        old_pump.stream_task.abort();
    }

    let stream_task = attachment.stream_task;
    let epoch = attachment.epoch;
    let mut messages = attachment.messages;
    let session_id_clone = session_id.clone();
    let app = app_handle.clone();

    let task = tokio::spawn(async move {
        let epoch_str = epoch.to_string();
        let mut buffer = Vec::with_capacity(BATCH_MAX_BYTES);
        let mut last_seq: Option<u64> = None;

        loop {
            if buffer.is_empty() {
                match messages.recv().await {
                    Some(DaemonStreamMessage::Output { sequence, data, .. }) => {
                        buffer.extend_from_slice(&data);
                        last_seq = Some(sequence);
                        while buffer.len() < BATCH_MAX_BYTES {
                            match messages.try_recv() {
                                Ok(DaemonStreamMessage::Output { sequence, data, .. }) => {
                                    buffer.extend_from_slice(&data);
                                    last_seq = Some(sequence);
                                }
                                Ok(DaemonStreamMessage::Lagged {
                                    end_sequence,
                                    history,
                                    ..
                                }) => {
                                    buffer.extend_from_slice(&history);
                                    if let Some(seq) = end_sequence {
                                        last_seq = Some(seq);
                                    }
                                }
                                Ok(DaemonStreamMessage::Exit { exit_code, .. }) => {
                                    if !buffer.is_empty() {
                                        flush_terminal_output(
                                            &app,
                                            &session_id_clone,
                                            &mut buffer,
                                            last_seq.take(),
                                            Some(&epoch_str),
                                        );
                                    }
                                    let _ = app.emit(
                                        TERMINAL_LIFECYCLE_EVENT,
                                        TerminalLifecyclePayload {
                                            session_id: session_id_clone.clone(),
                                            state: TerminalLifecycleState::Exited,
                                            exit_code,
                                            reason: None,
                                        },
                                    );
                                    return;
                                }
                                Ok(DaemonStreamMessage::Gap { .. }) => {}
                                Err(_) => break,
                            }
                        }
                        if buffer.len() >= BATCH_MAX_BYTES {
                            flush_terminal_output(
                                &app,
                                &session_id_clone,
                                &mut buffer,
                                last_seq.take(),
                                Some(&epoch_str),
                            );
                        }
                    }
                    Some(DaemonStreamMessage::Lagged {
                        end_sequence,
                        history,
                        ..
                    }) => {
                        buffer.extend_from_slice(&history);
                        if let Some(seq) = end_sequence {
                            last_seq = Some(seq);
                        }
                        flush_terminal_output(
                            &app,
                            &session_id_clone,
                            &mut buffer,
                            last_seq.take(),
                            Some(&epoch_str),
                        );
                    }
                    Some(DaemonStreamMessage::Gap { .. }) => {}
                    Some(DaemonStreamMessage::Exit { exit_code, .. }) => {
                        let _ = app.emit(
                            TERMINAL_LIFECYCLE_EVENT,
                            TerminalLifecyclePayload {
                                session_id: session_id_clone.clone(),
                                state: TerminalLifecycleState::Exited,
                                exit_code,
                                reason: None,
                            },
                        );
                        break;
                    }
                    None => {
                        break;
                    }
                }
            } else {
                tokio::select! {
                    msg = messages.recv() => {
                        match msg {
                            Some(DaemonStreamMessage::Output {
                                sequence,
                                data,
                                ..
                            }) => {
                                buffer.extend_from_slice(&data);
                                last_seq = Some(sequence);
                                while buffer.len() < BATCH_MAX_BYTES {
                                    match messages.try_recv() {
                                        Ok(DaemonStreamMessage::Output {
                                            sequence,
                                            data,
                                            ..
                                        }) => {
                                            buffer.extend_from_slice(&data);
                                            last_seq = Some(sequence);
                                        }
                                        Ok(DaemonStreamMessage::Lagged {
                                            end_sequence,
                                            history,
                                            ..
                                        }) => {
                                            buffer.extend_from_slice(&history);
                                            if let Some(seq) = end_sequence {
                                                last_seq = Some(seq);
                                            }
                                        }
                                        Ok(DaemonStreamMessage::Exit { exit_code, .. }) => {
                                            if !buffer.is_empty() {
                                                flush_terminal_output(
                                                    &app,
                                                    &session_id_clone,
                                                    &mut buffer,
                                                    last_seq.take(),
                                                    Some(&epoch_str),
                                                );
                                            }
                                            let _ = app.emit(
                                                TERMINAL_LIFECYCLE_EVENT,
                                                TerminalLifecyclePayload {
                                                    session_id: session_id_clone.clone(),
                                                    state: TerminalLifecycleState::Exited,
                                                    exit_code,
                                                    reason: None,
                                                },
                                            );
                                            return;
                                        }
                                        Ok(DaemonStreamMessage::Gap { .. }) => {}
                                        Err(_) => break,
                                    }
                                }
                                if buffer.len() >= BATCH_MAX_BYTES {
                                    flush_terminal_output(
                                        &app,
                                        &session_id_clone,
                                        &mut buffer,
                                        last_seq.take(),
                                        Some(&epoch_str),
                                    );
                                }
                            }
                            Some(DaemonStreamMessage::Lagged {
                                end_sequence,
                                history,
                                ..
                            }) => {
                                buffer.extend_from_slice(&history);
                                if let Some(seq) = end_sequence {
                                    last_seq = Some(seq);
                                }
                                flush_terminal_output(
                                    &app,
                                    &session_id_clone,
                                    &mut buffer,
                                    last_seq.take(),
                                    Some(&epoch_str),
                                );
                            }
                            Some(DaemonStreamMessage::Gap { .. }) => {}
                            Some(DaemonStreamMessage::Exit { exit_code, .. }) => {
                                if !buffer.is_empty() {
                                    flush_terminal_output(
                                        &app,
                                        &session_id_clone,
                                        &mut buffer,
                                        last_seq.take(),
                                        Some(&epoch_str),
                                    );
                                }
                                let _ = app.emit(
                                    TERMINAL_LIFECYCLE_EVENT,
                                    TerminalLifecyclePayload {
                                        session_id: session_id_clone.clone(),
                                        state: TerminalLifecycleState::Exited,
                                        exit_code,
                                        reason: None,
                                    },
                                );
                                break;
                            }
                            None => {
                                break;
                            }
                        }
                    }
                    _ = tokio::time::sleep(BATCH_FLUSH_INTERVAL) => {
                        flush_terminal_output(
                            &app,
                            &session_id_clone,
                            &mut buffer,
                            last_seq.take(),
                            Some(&epoch_str),
                        );
                    }
                }
            }
        }
        if !buffer.is_empty() {
            flush_terminal_output(
                &app,
                &session_id_clone,
                &mut buffer,
                last_seq.take(),
                Some(&epoch_str),
            );
        }

        let mut guard = ACTIVE_PUMPS.lock();
        if let Some(map) = guard.as_mut() {
            map.remove(&session_id_clone);
        }
    });

    map.insert(session_id, PumpHandle { task, stream_task });
}

